import os
from typing import Any, Dict, List, Optional

import requests


class TextContentSafetyScorer:
    """
    Scores text for unsafe or policy-violating content using the OpenAI Moderation API.
    """

    def __init__(self, api_key: Optional[str] = None, timeout: float = 30.0) -> None:
        self.api_key = api_key or os.getenv("OPENAI_API_KEY")
        if not self.api_key:
            raise ValueError("Missing OpenAI API key. Set OPENAI_API_KEY or pass api_key.")
        self.timeout = timeout
        self.endpoint = "https://api.openai.com/v1/moderations"

    def score(self, text: str) -> Dict[str, Any]:
        if not isinstance(text, str):
            raise TypeError("text must be a string")
        if not text.strip():
            raise ValueError("text must not be empty")

        payload = {
            "model": "omni-moderation-latest",
            "input": text,
        }
        headers = {
            "Authorization": f"Bearer {self.api_key}",
            "Content-Type": "application/json",
        }

        resp = requests.post(self.endpoint, headers=headers, json=payload, timeout=self.timeout)
        resp.raise_for_status()
        data = resp.json()

        results = data.get("results", [])
        if not results:
            raise ValueError("No moderation results returned by OpenAI")

        result = results[0]
        categories = result.get("categories", {})
        category_scores = result.get("category_scores", {})
        flagged = bool(result.get("flagged", False))

        unsafe_scores = {k: float(v) for k, v in category_scores.items()}
        sorted_risks = sorted(unsafe_scores.items(), key=lambda kv: kv[1], reverse=True)

        return {
            "flagged": flagged,
            "unsafe": flagged,
            "categories": {k: bool(v) for k, v in categories.items()},
            "scores": unsafe_scores,
            "top_risks": [
                {"category": category, "score": score}
                for category, score in sorted_risks[:5]
            ],
            "raw": result,
        }


def score_text_safety(text: str, api_key: Optional[str] = None) -> Dict[str, Any]:
    return TextContentSafetyScorer(api_key=api_key).score(text)
